schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/project-spec-structure.json",
  "type": "object",
  "required": ["location", "committed", "flat_files", "subdirs", "rebuild_test", "history_in_tree"],
  "additionalProperties": false,
  "properties": {
    "location": { "type": "string", "pattern": "^\\.aidocs/project-spec/$|^[^~].*/project-spec/$" },
    "committed": { "type": "boolean", "const": true },
    "constitution_declares_path": { "type": "boolean" },
    "flat_files": {
      "type": "array",
      "uniqueItems": true,
      "allOf": [
        { "contains": { "const": "AGENTS.md" } },
        { "contains": { "const": "CLAUDE.md" } },
        { "contains": { "const": "mission.md" } },
        { "contains": { "const": "glossary.md" } },
        { "contains": { "const": "business-rules.md" } },
        { "contains": { "const": "data-model.md" } },
        { "contains": { "const": "auth.md" } },
        { "contains": { "const": "deploy.md" } },
        { "contains": { "const": "config-secrets.md" } },
        { "contains": { "const": "non-functional.md" } },
        { "contains": { "const": "observability.md" } },
        { "contains": { "const": "invariants.md" } }
      ],
      "items": { "type": "string", "pattern": "^[a-z0-9-]+\\.md$|^AGENTS\\.md$|^CLAUDE\\.md$" }
    },
    "subdirs": {
      "type": "array",
      "minItems": 4,
      "allOf": [
        { "contains": { "properties": { "name": { "const": "domain" } } } },
        { "contains": { "properties": { "name": { "const": "api" } } } },
        { "contains": { "properties": { "name": { "const": "integrations" } } } },
        { "contains": { "properties": { "name": { "const": "decisions" } } } }
      ],
      "items": {
        "type": "object",
        "required": ["name", "agents_md", "claude_md"],
        "properties": {
          "name": { "type": "string", "pattern": "^[a-z0-9-]+$" },
          "agents_md": { "type": "boolean", "const": true },
          "claude_md": { "type": "boolean", "const": true }
        }
      }
    },
    "rebuild_test": {
      "type": "object",
      "required": ["event", "passed", "assumptions"],
      "properties": {
        "event": { "type": "string", "enum": ["end-of-feature", "post-cr-bug-deploy"] },
        "feature_or_fix": { "type": "string", "pattern": "^(F|CR|BUG)[0-9]{3,}$" },
        "passed": { "type": "boolean" },
        "assumptions": { "type": "array", "items": { "type": "string" } }
      }
    },
    "history_in_tree": { "type": "boolean", "const": false }
  }
}

output-contract.example:
{
  "location": ".aidocs/project-spec/",
  "committed": true,
  "flat_files": ["AGENTS.md", "CLAUDE.md", "mission.md", "glossary.md", "business-rules.md",
                 "data-model.md", "auth.md", "deploy.md", "config-secrets.md",
                 "non-functional.md", "observability.md", "invariants.md"],
  "subdirs": [
    {"name": "domain",       "agents_md": true, "claude_md": true},
    {"name": "api",          "agents_md": true, "claude_md": true},
    {"name": "integrations", "agents_md": true, "claude_md": true},
    {"name": "decisions",    "agents_md": true, "claude_md": true}
  ],
  "rebuild_test": {
    "event": "end-of-feature",
    "feature_or_fix": "F042",
    "passed": true,
    "assumptions": ["retry back-off for the mail provider is exponential (documented in integrations/mail.md)"]
  },
  "history_in_tree": false
}
